  assert.equal(orders.length, 3);
});

test('OrderRepository.findQuotes returns active quote orders', async () => {
  const orders = await new OrderRepository().findQuotes();
  assert.deepEqual(orders.map((order) => order.id), [11]);
  assert.ok(orders.every((order) => order.status === 'quote' && order.deleted_at === null));
