import { listActiveUsers, findUser, softDeleteUser } from '../src/services/user-service.js';
import { reset } from '../src/db.js';
import { UserRepository } from '../src/repositories/user-repository.js';

test('listActiveUsers excludes soft-deleted users', (t, done) => {
  listActiveUsers((err, users) => {
    assert.equal(err, null);
    assert.equal(users.length, 2);
    assert.ok(users.every((u) => u.deleted_at === null));
    done();
  });
});

test('findUser returns null for an unknown id', (t, done) => {
  findUser(999, (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    done();
  });
});

test('listActiveUsers passes repository errors to the callback', (t, done) => {
  const original = UserRepository.prototype.findActive;
  const failure = new Error('repository failed');
  UserRepository.prototype.findActive = () => Promise.reject(failure);
  t.after(() => { UserRepository.prototype.findActive = original; });

  listActiveUsers((err, users) => {
    assert.equal(err, failure);
    assert.equal(users, undefined);
    done();
  });
});

test('softDeleteUser updates the user through the repository', async () => {
  try {
    const deleted = await new Promise((resolve, reject) => {
      softDeleteUser(2, '2026-10-22', (err, user) => err ? reject(err) : resolve(user));
    });
    assert.equal(deleted.deleted_at, '2026-10-22');
    assert.equal((await new UserRepository().findById(2)).deleted_at, '2026-10-22');
  } finally {
    reset();
  }
});
